INSERT INTO etl_jobs (id, job_key, job_name, description, calculation_logic, schedule, status, last_run, last_result, created_at) VALUES (1, 'gross-margin', '签单毛利指标计算', '按年份/区域聚合签单毛利、签单毛利率', '数据源：总合同表（数据源管理最新版）。字段映射：「统计日期」→年份、「区域」分组、「合同总金额」+「签单毛利」求和。计算：签单毛利率 = 签单毛利 ÷ 合同总金额。产出：indicator_metrics 宽表（dim_type=year 按年份、dim_type=region 按区域×年份）。', '0 2 * * *', 'stopped', '2026-08-16 00:40:29', '成功', '2026-08-15 23:20:56');
INSERT INTO etl_jobs (id, job_key, job_name, description, calculation_logic, schedule, status, last_run, last_result, created_at) VALUES (2, 'payment-cycle', '回款周期指标计算', '按合同聚合回款周期指标', '数据源：总合同表 + 项目里程碑表。口径：按合同编号关联回款记录，取最后一笔回款日期；回款周期 = 最后一笔回款日 − 合同签订日（统计日期）；按合同聚合。产出：payment_cycle_metrics 宽表（每合同一行）。', '0 3 * * *', 'stopped', '', '', '2026-08-15 23:20:56');
INSERT INTO etl_jobs (id, job_key, job_name, description, calculation_logic, schedule, status, last_run, last_result, created_at) VALUES (3, 'sign-summary', '签约汇总指标计算', '按业务线/区域聚合签约合同额', '数据源：总合同表。口径：按「业务线」「区域」分组，聚合当年生效合同额与签约合同数。（骨架阶段，计算逻辑待实现）', '0 4 * * *', 'stopped', '', '', '2026-08-15 23:20:56');
INSERT INTO etl_jobs (id, job_key, job_name, description, calculation_logic, schedule, status, last_run, last_result, created_at) VALUES (4, 'fund-occupancy', '资金占用指标计算', 'FIFO 垫资冲抵，计算每个合同的资金占用、加权资金占用、资金成本', '数据源：付款明细表 + 收款明细表。口径：按合同编号透视（付款/收款按日期聚合）→ FIFO 先进先出冲抵 → 预收款冲抵后续付款 → 生成垫资片段（SETTLED/OCCUPYING）。计算：当前资金占用=占用中片段金额和；元天合计=片段金额×占用天数；预估资金成本=元天×日利率（年化3%）。产出：fund_metrics 宽表（每合同一行）。', '0 5 * * *', 'stopped', '', '', '2026-08-15 23:20:56');
